package in.aicon.pocket;
import android.content.Context;import java.lang.reflect.Constructor;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class BackgroundSyncTest {
 Context context;AccountDirectory accounts;String a="1234567890",b="9876543210";
 VerifiedDriveAccess identity(String subject)throws Exception{Constructor<VerifiedDriveAccess> c=VerifiedDriveAccess.class.getDeclaredConstructor(String.class,String.class,String.class);c.setAccessible(true);return c.newInstance(subject,subject+"@example.invalid","fake-test-token");}
 @Before public void setup()throws Exception{try{androidx.work.WorkManager.getInstance(RuntimeEnvironment.getApplication());}catch(IllegalStateException init){androidx.work.WorkManager.initialize(RuntimeEnvironment.getApplication(),new androidx.work.Configuration.Builder().setMinimumLoggingLevel(android.util.Log.ERROR).build());}context=RuntimeEnvironment.getApplication();context.getSharedPreferences("hisab-account-directory",0).edit().clear().commit();for(String s:new String[]{a,b}){context.deleteDatabase(AccountScope.databaseFor(s));context.getSharedPreferences("hisab-sync-status-"+AccountScope.databaseFor(s),0).edit().clear().commit();}accounts=new AccountDirectory(context);accounts.record(identity(a));accounts.selectKnown(a);}
 @Test public void selectedAccountSyncClearsItsTransientTokenAndSavesOnlyStatus()throws Exception{VerifiedDriveAccess access=identity(a);assertEquals(BackgroundSync.Outcome.DONE,BackgroundSync.run(context,a,(c,e)->access,(s,t,v,g)->{g.requireCurrent();assertSame(access,v);assertTrue(s.accountLedger());},()->{}));try{access.accessToken(a);fail();}catch(DriveAppData.NeedsSignIn expected){}assertEquals("READY",new SyncStatusStore(context,a).get().state);assertTrue(new SyncStatusStore(context,a).get().success>0);}
 @Test public void queuedOldAccountCannotAuthorizeWhenSelectionChanged()throws Exception{accounts.selectLocal();assertEquals(BackgroundSync.Outcome.NO_LONGER_SELECTED,BackgroundSync.run(context,a,(c,e)->{fail();return null;},(s,t,v,g)->fail(),()->{}));}
 @Test public void selectionChangeDuringAuthorizationStopsBeforeAnySync()throws Exception{VerifiedDriveAccess access=identity(a);assertEquals(BackgroundSync.Outcome.NO_LONGER_SELECTED,BackgroundSync.run(context,a,(c,e)->{accounts.selectLocal();return access;},(s,t,v,g)->fail(),()->{}));try{access.accessToken(a);fail();}catch(DriveAppData.NeedsSignIn expected){}}
 @Test public void differentGoogleIdentityNeverRunsAndRequiresReconnect()throws Exception{VerifiedDriveAccess other=identity(b);assertEquals(BackgroundSync.Outcome.NEEDS_REVIEW,BackgroundSync.run(context,a,(c,e)->other,(s,t,v,g)->fail(),()->{}));assertEquals("NEEDS_SIGN_IN",new SyncStatusStore(context,a).get().state);}
 @Test public void pendingResetStopsBeforeAuthorizationAndEdit()throws Exception{try(LedgerSession session=LedgerSession.remembered(context,accounts,a)){session.beginCloudReset(session.ticket());}assertEquals(BackgroundSync.Outcome.NEEDS_REVIEW,BackgroundSync.run(context,a,(c,e)->{fail();return null;},(s,t,v,g)->fail(),()->{}));assertEquals("RESET_PENDING",new SyncStatusStore(context,a).get().state);}
 @Test public void rateLimitsRetryButPermissionRequestsStayQuiet()throws Exception{assertEquals(BackgroundSync.Outcome.RETRY,BackgroundSync.run(context,a,(c,e)->identity(a),(s,t,v,g)->{throw new DriveAppData.RetryLater();},()->{}));assertEquals("RETRY",new SyncStatusStore(context,a).get().state);assertEquals(BackgroundSync.Outcome.NEEDS_REVIEW,BackgroundSync.run(context,a,(c,e)->{throw new DriveAppData.NeedsSignIn();},(s,t,v,g)->fail(),()->{}));assertEquals("NEEDS_SIGN_IN",new SyncStatusStore(context,a).get().state);}
 @Test public void pendingDisconnectStopsEvenAlreadyAuthorizedBackgroundWork()throws Exception{accounts.beginDisconnect(a);assertEquals(BackgroundSync.Outcome.NO_LONGER_SELECTED,BackgroundSync.run(context,a,(c,e)->{fail();return null;},(s,t,v,g)->fail(),()->{}));}

}
